package com.farm2market.controller;
import com.farm2market.entity.*; import com.farm2market.repository.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/farmers/me") @PreAuthorize("hasRole('FARMER')") public class FarmerController {final UserRepository users;final ProductRepository products;final OrderRepository orders;FarmerController(UserRepository u,ProductRepository p,OrderRepository o){users=u;products=p;orders=o;} User current(UserDetails a){return users.findByEmail(a.getUsername()).orElseThrow();} @GetMapping public User me(@AuthenticationPrincipal UserDetails a){return current(a);} @GetMapping("/products") public List<Product> ps(@AuthenticationPrincipal UserDetails a){return products.findByFarmer(current(a));} @GetMapping("/orders") public List<Order> os(@AuthenticationPrincipal UserDetails a){return orders.findByFarmerOrderByCreatedAtDesc(current(a));}}
